CREATE VIEW Vue_StkLedger AS SELECT '1' AS TrsTypeno, 'Opening' AS TrsType, Coycode, OpenDt AS TrsDate, 0 AS DocNo, Finyear, '' AS Pname, '' AS PartyDCref, StockID, RlsBg AS InBg, Kgs AS InKg, MtrPc AS InMtr, 0 AS OutBg, 0 AS OutKg, 0 AS OutMtr, Trs_Opening.GodID,Dept FROM   Trs_Opening  UNION ALL  SELECT     '2' AS TrsTypeNo, 'Purchase GRN' AS TrsType, Trs_Grn1.Coycode, Trs_Grn1.dt AS TrsDate, Trs_Grn1.DocNo, Trs_Grn1.Finyear, Mas_Party.Pname, Trs_Grn1.PartyDCref, Trs_GRN2.StockID, Trs_GRN2.RBag AS InBg, Trs_GRN2.RecKgs AS InKg, Trs_GRN2.Recmtr AS InMtr, 0 AS OutBg, 0 AS OutKg,  0 AS OutMtr, Trs_Grn1.GodID,Trs_Grn1.Dept FROM         Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN Mas_Party ON Trs_Grn1.SuppID = Mas_Party.PID WHERE    Trs_Grn1.GRNType = 'Purchase'  UNION ALL  SELECT     '3' AS TrsTypeNo, 'Purchase Return' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear, Mas_Party.Pname, '' AS PDCRef, Trs_Del2.StockID, 0 AS InBag, 0 AS InKg, 0 AS InMtr, Trs_Del2.BgRl, Trs_Del2.Kg, Trs_Del2.mtr, Trs_Del1.GodID,Trs_Del1.Prs_Dept as Dept FROM       Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN Mas_Party ON Trs_Del1.Party = Mas_Party.PID WHERE     Trs_Del1.TrType = 4   UNION ALL  SELECT  '4' AS TrsTypeNo, 'Process Delivery' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear, Mas_Party.Pname, '' AS PDCRef, Trs_Del2.StockID, 0 AS InBag, 0 AS InKg, 0 AS InMtr, Trs_Del2.BgRl, Trs_Del2.Kg, Trs_Del2.mtr, Trs_Del1.GodID,stocktable.dept as Dept FROM         Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN Mas_Party ON Trs_Del1.Party = Mas_Party.PID inner join stocktable on trs_del2.stockid=stocktable.stockid  WHERE     Trs_Del1.TrType = 1  UNION ALL  SELECT  '5' AS TrsTypeNo, 'Process Receipt' AS TrsType, Trs_Grn1.Coycode, Trs_Grn1.dt AS TrsDate, Trs_Grn1.DocNo, Trs_Grn1.Finyear, Mas_Party.Pname,  Trs_Grn1.PartyDCref, Trs_GRN2.StockID, Trs_GRN2.RBag AS InBg, Trs_GRN2.RecKgs AS InKg, Trs_GRN2.Recmtr AS InMtr, 0 AS OutBg, 0 AS OutKg,  0 AS OutMtr, Trs_Grn1.GodID,Trs_Grn1.Dept FROM         Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN Mas_Party ON Trs_Grn1.SuppID = Mas_Party.PID WHERE     Trs_Grn1.GRNType IN ('Process', 'DirectReceipt') UNION ALL SELECT     '6' AS TrsTypeNo, 'Process Return ' AS TrsType, Trs_Grn1.Coycode, Trs_Grn1.dt AS TrsDate, Trs_Grn1.DocNo, Trs_Grn1.Finyear, Mas_Party.Pname,  Trs_Grn1.PartyDCref, Trs_GRN2.StockID, Trs_GRN2.RBag AS InBg,  Trs_GRN2.RecKgs AS InKg, Trs_GRN2.Recmtr AS InMtr, 0 AS OutBg, 0 AS OutKg,  0 AS OutMtr, Trs_Grn1.GodID,stocktable.Dept FROM         Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN Mas_Party ON Trs_Grn1.SuppID = Mas_Party.PID inner join stocktable on trs_grn2.stockid= stocktable.stockid WHERE     Trs_Grn1.GRNType = 'Process Return'  UNION ALL SELECT     '7' AS TrsTypeno, 'Transfer Out' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear,  RTRIM(CAST(OrderMas.Jobno AS varchar)) + '/' + OrderMas.Finyear + '->' + OrderMas.BuyOrdNo AS OrderNo, '' AS PdcRef,  Trs_Del2.StockID AS StockId, 0 AS InBag, 0 AS InKgs, 0 AS Inmtr, Trs_Del2.BgRl AS OutBag, Trs_Del2.Kg AS OutKg, Trs_Del2.mtr AS OutMtr, Trs_Del1.GodID,Trs_Del1.Prs_Dept as Dept FROM  Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN OrderMas ON Trs_Del2.TranOrdID = OrderMas.OrdId WHERE     Trs_Del2.TranID > 0 AND Trs_Del1.TrType = 3    UNION ALL    SELECT     '8' AS TrsTypeno, 'Transfer In' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear,  RTRIM(CAST(OrderMas.Jobno AS varchar)) + '/' + OrderMas.Finyear + '->' + OrderMas.BuyOrdNo AS OrderNo, '' AS PdcRef, Trs_Del2.TranID AS StockId,  Trs_Del2.BgRl AS InBag, Trs_Del2.Kg AS InKgs, Trs_Del2.mtr AS Inmtr, 0 AS OutBag, 0 AS OutKg, 0 AS OutMtr, Trs_Del1.GodID,Trs_Del1.Prs_Dept As Dept FROM         Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN OrderMas ON Trs_Del2.OrdID = OrderMas.OrdId WHERE     Trs_Del2.TranID > 0 AND Trs_Del1.TrType = 3 UNION ALL SELECT     '9' AS TrsTypeNo, 'Sales Delivery' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear, Mas_Party.Pname, '' AS PDCRef,  Trs_Del2.StockID, 0 AS InBag, 0 AS InKg, 0 AS InMtr, Trs_Del2.BgRl, Trs_Del2.Kg, Trs_Del2.mtr, Trs_Del1.GodID ,Trs_Del1.Prs_Dept as Dept FROM         Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN Mas_Party ON Trs_Del1.Party = Mas_Party.PID WHERE     Trs_Del1.TrType = 2   UNION ALL   SELECT     '10' AS TrsTypeNo, 'Saless Return' AS TrsType, Trs_Grn1.Coycode, Trs_Grn1.dt AS TrsDate, Trs_Grn1.DocNo, Trs_Grn1.Finyear, Mas_Party.Pname,  Trs_Grn1.PartyDCref, Trs_GRN2.StockID, Trs_GRN2.RBag AS InBg, Trs_GRN2.RecKgs AS InKg, Trs_GRN2.Recmtr AS InMtr, 0 AS OutBg, 0 AS OutKg,  0 AS OutMtr, Trs_Grn1.GodID ,Trs_grn1.Dept FROM   Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN Mas_Party ON Trs_Grn1.SuppID = Mas_Party.PID WHERE     Trs_Grn1.GRNType = 'Sales Return'  UNION ALL  SELECT     '11' AS TrsTypeNo, 'Stock Ajustment Plus' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear, '' AS Pname, '' AS PDCRef,  Trs_Del2.StockID, Trs_Del2.BgRl, Trs_Del2.Kg, Trs_Del2.mtr, 0 AS InBag, 0 AS InKg, 0 AS InMtr, Trs_Del1.GodID,Trs_Del1.Prs_Dept as Dept FROM  Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID WHERE  Trs_Del1.TrType = 5 AND Trs_Del2.StockAddLess = 'Add'    UNION ALL    SELECT     '12' AS TrsTypeNo, 'Stock Ajustment Minus' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear, '' AS pname, '' AS PDCRef, Trs_Del2.StockID, 0 AS InBag, 0 AS InKg, 0 AS InMtr, Trs_Del2.BgRl, Trs_Del2.Kg, Trs_Del2.mtr, Trs_Del1.GodID,Trs_Del1.Prs_Dept as Dept FROM Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID WHERE  Trs_Del1.TrType = 5 AND Trs_Del2.StockAddLess = 'Less'   UNION ALL     SELECT '13' AS TrsTypeNo, 'Godown Transfer In' as TrsType, Trs_Del1.CoyCode, Trs_Del1.Dt, Trs_Del1.Docno, Trs_Del1.Finyear, Mas_Godown.GodName as Pname, '' AS PdcRef, Trs_Del2.StockID AS StockId,  Trs_Del2.BgRl AS InBag, Trs_Del2.Kg AS InKgs, Trs_Del2.mtr AS Inmtr, 0 AS OutBag, 0 AS OutKg, 0 AS OutMtr, Trs_Del1.Party as GodID,Trs_Del1.Prs_Dept as Dept FROM Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN OrderMas ON Trs_Del2.OrdID = OrderMas.OrdId INNER JOIN  Mas_Godown ON Trs_Del1.Party = Mas_Godown.GodID WHERE Trs_Del1.TrType = 14    UNION ALL      SELECT '14' AS TrsTypeNo, 'Godown Transfer Out' as TrsType, Trs_Del1.CoyCode, Trs_Del1.Dt, Trs_Del1.Docno, Trs_Del1.Finyear, Mas_Godown.GodName as Pname, '' AS PdcRef, Trs_Del2.StockID AS StockId,  0 AS InBag, 0 AS InKgs, Trs_Del2.mtr AS Inmtr, Trs_Del2.BgRl AS OutBag, Trs_Del2.Kg AS OutKg, 0 AS OutMtr, Trs_Del1.GodID as GodID,Trs_Del1.Prs_Dept as Dept FROM Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN OrderMas ON Trs_Del2.OrdID = OrderMas.OrdId INNER JOIN Mas_Godown ON Trs_Del1.Godid = Mas_Godown.GodID WHERE Trs_Del1.TrType = 14    UNION ALL      SELECT '15' as TrsTypeno,'CutAck' AS Trstype, Trs_CutApr. CoyCode,Trs_Del1.Dt AS TrsDate,Trs_CutApr.AprNo as DocNo,Trs_CutApr.Finyear, '' as pName,'' as PartyDCref,Trs_Del2.tranid as stockid, Trs_Del2.Arl AS InBg, Trs_Del2.AKg AS Inkg, Trs_Del2.AMtr AS Inmtr,0 as outbg,0 as outkg,0 as outmtr,Trs_CutApr.GodID as GodID,stocktable.Dept as Dept FROM Trs_Del2 INNER JOIN Trs_Del1 ON Trs_Del2.ID = Trs_Del1.ID INNER JOIN Trs_CutApr ON Trs_Del1.PrdID = Trs_CutApr.ID inner join stocktable on trs_del2.tranid=stocktable.stockid  where trtype in(1,17)    UNION ALL   Select '16'  as TrsTypeno,'UnitDc' As Trstype,trs_del1.coycode,trs_del1.Dt,trs_del1.Docno,trs_del1.finyear,'' as Pname,'' as PartyDCref,trs_del2.stockid,0 as inbg,0 as Inkg, 0 as InMtr,trs_del2.BgRl OutBg,trs_del2.Kg as OutKg,trs_del2.Mtr as outmtr,trs_del1.Godid,stocktable.dept as dept from trs_del1 inner join trs_del2 on trs_del1.id=trs_del2.id inner join stocktable on trs_del2.stockid=stocktable.stockid  where trtype=-2   UNION ALL    Select '17' as TrsTypeno,'UnitreturnAck' As Trstype,Trs_CutApr.coycode,Trs_CutApr.AprDt,Trs_CutApr.Aprno,Trs_CutApr.finyear,'' as Pname,'' as PartyDCref,trs_del2.tranid,0 as inbg,0 as Inkg, 0 as InMtr,trs_del2.aRl OutBg,trs_del2.aKg as OutKg,trs_del2.aMtr as outmtr,Trs_CutApr.Godid , stocktable.dept from trs_del1 inner join trs_del2 on trs_del1.id=trs_del2.id  inner join stocktable on trs_del2.tranid=stocktable.stockid INNER JOIN Trs_CutApr ON trs_del2.AID = Trs_CutApr.ID    where trtype=-2 and isnull(aid,0)>0  and DELTYPE <> 'R'  UNION ALL     Select '18' as TrsTypeno,'Unit-fabric deliveryreturn' As Trstype,Trs_grn1.coycode,Trs_grn1.Dt,Trs_grn1.docno,Trs_grn1.finyear,'' as Pname,'' as PartyDCref,Trs_grn2.stockid,Trs_grn2.RBag as inbg,Trs_grn2.RecKgs as Inkg, Trs_grn2.RecMtr as InMtr,0 OutBg,0 as OutKg,0 as outmtr,Trs_grn1.Godid , stocktable.dept FROM Trs_grn1 inner join Trs_grn2 on Trs_grn1.id=Trs_grn2.id  inner join stocktable on Trs_grn2.stockid=stocktable.stockid  where grntype='FabricRetToUnit'  UNION ALL  Select '19' as TrsTypeno,'ReturnTOLot' As Trstype,Trs_CutApr.coycode,Trs_CutApr.AprDt,Trs_CutApr.Aprno,Trs_CutApr.finyear,'' as Pname,'' as PartyDCref,trs_del2.tranid,trs_del2.aRl as inbg,trs_del2.aKg as Inkg, trs_del2.aMtr as InMtr,0 OutBg,0 as OutKg,0 as outmtr,Trs_CutApr.Godid , stocktable.dept from trs_del1 inner join trs_del2 on trs_del1.id=trs_del2.id  inner join stocktable on trs_del2.tranid=stocktable.stockid INNER JOIN Trs_CutApr ON trs_del2.AID = Trs_CutApr.ID    where trtype=-2 and isnull(aid,0)>0    and DELTYPE='R'  UNION ALL  SELECT     '20' AS TrsTypeno, 'ReadyToCutIN' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear,  RTRIM(CAST(OrderMas.Jobno AS varchar)) + '/' + OrderMas.Finyear + '->' + OrderMas.BuyOrdNo AS OrderNo, '' AS PdcRef, Trs_Del2.TranID AS StockId,  Trs_Del2.BgRl AS InBag, Trs_Del2.Kg AS InKgs, Trs_Del2.mtr AS Inmtr,  0 AS OutBag, 0 AS OutKg, 0 AS OutMtr, Trs_Del1.GodID,Trs_Del1.Prs_Dept As Dept FROM  Trs_ReadyToCut1 as  Trs_Del1 INNER JOIN Trs_ReadyToCut2 as Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN OrderMas ON Trs_Del2.OrdID = OrderMas.OrdId WHERE     Trs_Del2.TranID > 0 AND Trs_Del1.TrType = 20 UNION ALL  SELECT     '20' AS TrsTypeno, 'OUT_FinalPrs' AS TrsType, Trs_Del1.Coycode, Trs_Del1.Dt, Trs_Del1.DocNo, Trs_Del1.Finyear,  RTRIM(CAST(OrderMas.Jobno AS varchar)) + '/' + OrderMas.Finyear + '->' + OrderMas.BuyOrdNo AS OrderNo, '' AS PdcRef, Trs_Del2.stockid AS StockId,  0 AS InBag, 0 AS InKgs, 0 AS Inmtr, Trs_Del2.BgRl AS OutBag, Trs_Del2.Kg AS OutKg, Trs_Del2.mtr AS OutMtr, Trs_Del1.GodID,stocktable.Dept As Dept FROM  Trs_ReadyToCut1 as  Trs_Del1 INNER JOIN Trs_ReadyToCut2 as Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN OrderMas ON Trs_Del2.OrdID = OrderMas.OrdId inner join StockTable on trs_del2.StockID = StockTable.StockID WHERE     Trs_Del2.stockid > 0 AND Trs_Del1.TrType = 20 